from pathlib import Path
import json

root=Path(__file__).parent/'dist'
pages=[
dict(file='index.html',name='К морю',label='01 / У ВОДЫ',title='Где волны задают<br><i>ритм дня.</i>',intro='Небольшое путешествие без большого плана. Солёный воздух, пустой берег и время, которое снова принадлежит вам.',image='photo-1473116763249-2faaef81ccda',subtitle='Один день, три простых радости',activities=[('01','Встретить утро','Пройти вдоль воды, пока берег ещё тихий. Найти свой темп и не смотреть на часы.'),('02','Свернуть с маршрута','Заглянуть на небольшую улочку, взять кофе с собой и выбрать скамейку с видом.'),('03','Остаться до заката','Захватить плед и проводить день у воды. Иногда этого вполне достаточно.')],tips=['Ветровка для прохладного вечера','Вода и небольшой перекус','Удобная обувь для долгой прогулки'],accent='#a6442c',note='Пусть единственным расписанием будет прилив.'),
dict(file='mountains.html',name='В горы',label='02 / ВЫШЕ ОБЛАКОВ',title='Чуть выше шума.<br><i>Чуть ближе к себе.</i>',intro='Тропинка, свежий воздух и широкий горизонт. Не обязательно покорять вершину, чтобы почувствовать простор.',image='photo-1464822759023-fed622ff2c3b',subtitle='День с новым горизонтом',activities=[('01','Выбрать простую тропу','Начать с короткого обозначенного маршрута, который подходит вашей подготовке.'),('02','Сделать паузу','Остановиться на удобной площадке, достать термос и рассмотреть пейзаж.'),('03','Вернуться засветло','Оставить запас времени на обратный путь и ещё один красивый вид.')],tips=['Проверить прогноз перед выходом','Взять воду, тёплый слой и карту','Сообщить близким маршрут и время возвращения'],accent='#485c43',note='Хороший маршрут — тот, на котором вам комфортно.'),
dict(file='forest.html',name='В лес',label='03 / СРЕДИ ДЕРЕВЬЕВ',title='Меньше спешки.<br><i>Больше воздуха.</i>',intro='Выбраться туда, где пахнет хвоей, свет просачивается сквозь ветви, а привычные мысли становятся тише.',image='photo-1448375240586-882707db888b',subtitle='Маленькие открытия по дороге',activities=[('01','Замедлить шаг','Выбрать знакомую прогулочную тропу и дать себе время замечать детали.'),('02','Прислушаться','Убрать наушники. Услышать ветер, птиц и хруст веточек под ногами.'),('03','Найти свой кадр','Посмотреть на свет между деревьями. Сохранить один момент на память.')],tips=['Скачать карту до прогулки','Выбрать закрытую обувь и одежду по погоде','Забрать с собой весь мусор'],accent='#42644d',note='Оставьте после себя только следы на тропинке.')]

css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f6f3eb;color:#292d28;font-family:Arial,sans-serif}a{color:inherit}header{height:98px;max-width:1344px;margin:auto;padding:0 60px;display:flex;align-items:center;justify-content:space-between}.logo{text-decoration:none;font-family:Georgia,serif;font-size:39px;letter-spacing:-2px}.logo span{color:var(--accent)}nav{display:flex;gap:32px}nav a{text-decoration:none;font-size:14px;padding:10px 0;color:#6c7066}nav a[aria-current]{color:#292d28;border-bottom:1px solid var(--accent)}.edition{font-size:10px;letter-spacing:2px;color:#777b70}main{max-width:1344px;margin:auto;padding:0 60px}.hero{display:grid;grid-template-columns:1fr 1fr;min-height:600px;border-top:1px solid #d9d9cd}.intro{padding:57px 48px 40px 0;display:flex;flex-direction:column;align-items:flex-start}.eyebrow{font-size:10px;font-weight:bold;letter-spacing:2px;color:var(--accent);margin:0 0 42px}h1{font:normal clamp(42px,4.5vw,68px)/1.05 Georgia,serif;letter-spacing:-2px;margin:0 0 25px}h1 i{font-weight:normal;color:var(--accent)}.description{font-size:15px;line-height:1.8;max-width:370px;color:#6b6e63;margin:0 0 30px}.button{padding:16px 22px;background:var(--accent);color:#fff;text-decoration:none;font-size:12px;display:inline-flex;gap:28px;align-items:center}.micro{margin-top:auto;padding-top:40px;font-size:10px;letter-spacing:1.5px;color:#7b7e72}.photograph{position:relative;min-height:570px;margin:22px 0 22px 10px;overflow:hidden;background:#bdc6bd}.photograph img{width:100%;height:100%;position:absolute;object-fit:cover}.photograph:after{content:'';position:absolute;inset:50% 0 0;background:linear-gradient(transparent,#142b2c66)}.caption{position:absolute;bottom:27px;left:27px;z-index:1;color:white;font-size:10px;letter-spacing:2px}.photo-number{position:absolute;right:24px;top:24px;color:#fff;border:1px solid #ffffff80;border-radius:50%;width:42px;height:42px;display:grid;place-items:center;font:italic 18px Georgia,serif}.discover{padding:63px 0 60px;border-top:1px solid #d9d9cd}.section-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:35px}h2{font:normal 34px Georgia,serif;letter-spacing:-.7px;margin:0}.section-head span{font-size:10px;letter-spacing:1.4px;color:#7b7e72}.activities{display:grid;grid-template-columns:repeat(3,1fr);gap:40px}.activity{border-top:1px solid #d4d5c9;padding-top:19px}.number{font:italic 25px Georgia,serif;color:var(--accent)}h3{font:normal 24px Georgia,serif;margin:18px 0 12px}.activity p{color:#707367;font-size:13px;line-height:1.8;max-width:310px}.prepare{background:#eaece0;padding:40px 44px;display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-bottom:38px}.prepare .eyebrow{margin:0 0 16px}.prepare h2{font-size:31px}.prepare p{font:italic 17px/1.5 Georgia,serif;color:#737868;max-width:310px}.checklist{list-style:none;padding:0;margin:0;align-self:center}.checklist li{border-bottom:1px solid #ced3c3;padding:15px 0;display:flex;gap:14px;font-size:12px;line-height:1.6}.checklist li:last-child{border:0}.tick{color:var(--accent)}footer{max-width:1224px;padding:0 0 28px;margin:auto;display:flex;justify-content:space-between;color:#858879;font-size:10px;letter-spacing:.7px}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px}@media(max-width:760px){header{padding:0 24px;height:86px}.edition{display:none}nav{gap:18px}nav a{font-size:12px}main{padding:0 24px}.hero{grid-template-columns:1fr}.intro{padding:36px 0 26px}.eyebrow{margin-bottom:28px}h1{font-size:49px}.description{max-width:480px}.micro{padding-top:28px}.photograph{margin:0 0 28px;min-height:400px}.discover{padding:36px 0}.section-head{display:block}h2{font-size:29px}.section-head span{display:block;margin-top:16px}.activities{grid-template-columns:1fr;gap:20px}.activity p{max-width:none}.prepare{padding:28px;grid-template-columns:1fr;gap:16px}.prepare p{max-width:none}footer{padding:0 24px 24px;gap:20px;line-height:1.6}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
(root/'style.css').write_text(css,encoding='utf-8')
for n,p in enumerate(pages):
 nav=''.join(f'<a href="{x["file"]}"'+(' aria-current="page"' if x==p else '')+f'>{x["name"]}</a>' for x in pages)
 acts=''.join(f'<article class="activity"><span class="number">{num}</span><h3>{title}</h3><p>{desc}</p></article>' for num,title,desc in p['activities'])
 tips=''.join(f'<li><span class="tick" aria-hidden="true">✓</span>{t}</li>' for t in p['tips'])
 html=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{p['name']} — Тише</title><meta name="description" content="{p['intro']}"><link rel="stylesheet" href="style.css"></head><body style="--accent:{p['accent']}"><header><a class="logo" href="index.html" aria-label="Тише — главная">тише<span>.</span></a><nav aria-label="Направления">{nav}</nav><span class="edition">ЖУРНАЛ МАЛЕНЬКИХ ПУТЕШЕСТВИЙ</span></header><main><section class="hero" aria-labelledby="title"><div class="intro"><p class="eyebrow">{p['label']}</p><h1 id="title">{p['title']}</h1><p class="description">{p['intro']}</p><a class="button" href="#ideas">Поймать настроение <span aria-hidden="true">↗</span></a><span class="micro">БЛИЖЕ К ПРИРОДЕ · БЛИЖЕ К СЕБЕ</span></div><div class="photograph"><img src="https://images.unsplash.com/{p['image']}?auto=format&amp;fit=crop&amp;w=1400&amp;q=85" alt="{'Морские волны у берега' if n==0 else 'Горные вершины' if n==1 else 'Солнечный свет в лесу'}" fetchpriority="high"><span class="photo-number">0{n+1}</span><span class="caption">ВРЕМЯ ВЫДОХНУТЬ</span></div></section><section class="discover" id="ideas" aria-labelledby="ideas-title"><div class="section-head"><h2 id="ideas-title">{p['subtitle']}</h2><span>НЕ ПЛАН. ВДОХНОВЕНИЕ.</span></div><div class="activities">{acts}</div></section><section class="prepare" aria-labelledby="prepare-title"><div><p class="eyebrow">ПЕРЕД ВЫХОДОМ</p><h2 id="prepare-title">Возьмите самое нужное.</h2><p>{p['note']}</p></div><ul class="checklist">{tips}</ul></section></main><footer><span>тише. © 2026</span><span>Идеи для поездок · В своём темпе</span></footer></body></html>'''
 (root/p['file']).write_text(html,encoding='utf-8')
 assert html.count('<section ')==3
for p in pages:
 assert (root/p['file']).exists()
print('Verified: 3 pages, 3 content sections per page, navigation targets exist.')
